# integration_missing_agecomp ----
## Setup ----
data("data_big")

# The gradient is evaluated here because the TMB object cannot be used after
# clear() frees the C++ objects.
report_and_gradient_for_data <- function(data) {
  data_4_model <- FIMSFrame(data)
  fit <- setup_default_parameters(data = data_4_model) |>
    initialize_fims(data = data_4_model) |>
    fit_fims(optimize = FALSE)
  obj <- get_obj(fit)
  output <- list(
    report = get_report(fit),
    gradient = as.numeric(obj[["gr"]](obj[["par"]]))
  )
  clear()
  output
}

# Drop the age composition for 1 year of each fleet, leaving age compositions
# in every other year. fleet1 has catch data, so its age composition comes
# from catch at age; survey1 has no catch data, so its age composition comes
# from index numbers at age. Both fleets also have length compositions.
data_missing_agecomp <- data_big |>
  dplyr::filter(
    !(type == "age_comp" & fleet == "fleet1" & timing == 3),
    !(type == "age_comp" & fleet == "survey1" & timing == 5)
  )

output_full <- report_and_gradient_for_data(data_big)
output_missing <- report_and_gradient_for_data(data_missing_agecomp)

## Edge handling ----
test_that("missing age composition in 1 year does not give NaN likelihoods", {
  #' @description Test that removing 1 year of age-composition data from fishery and survey fleets with length-composition data keeps every likelihood component finite.
  expect_true(
    all(is.finite(output_missing[["report"]][["nll_components"]]))
  )
})

test_that("missing age composition in 1 year does not give NaN gradients", {
  #' @description Test that removing 1 year of age-composition data from fishery and survey fleets with length-composition data keeps every gradient element finite.
  expect_true(all(is.finite(output_missing[["gradient"]])))
})

test_that("expected length composition does not depend on age-composition data", {
  #' @description Test that the expected length-composition proportions are unchanged when 1 year of age-composition data is removed, because they depend only on numbers at age and the age-to-length conversion.
  lengthcomp_full <- output_full[["report"]][["lengthcomp_proportion"]]
  lengthcomp_missing <- output_missing[["report"]][["lengthcomp_proportion"]]
  for (i in seq_along(lengthcomp_full)) {
    expect_equal(lengthcomp_missing[[i]], lengthcomp_full[[i]])
  }
})
